  "html": "<div class=\"fp-col\"><div class=\"fp-row\"><span class=\"fp-tag\">fetch</span><div class=\"fp-box mut\">remote</div><div class=\"fp-arrow fp-travel\">→</div><div class=\"fp-box acc fp-pulse-a\">origin/main</div><div class=\"fp-box\">локал ✋</div></div><div class=\"fp-row\"><span class=\"fp-tag\">pull</span><div class=\"fp-box mut\">remote</div><div class=\"fp-arrow fp-travel\" style=\"animation-delay:.4s\">→</div><div class=\"fp-box acc\">origin/main</div><div class=\"fp-arrow fp-travel\" style=\"animation-delay:.9s\">→</div><div class=\"fp-box good fp-pulse-g\" style=\"animation-delay:1.3s\">локал ✅</div></div></div>",
